#!/usr/bin/env node
// bundle copy generated by scripts/sync-assets.mjs: main-guard keyed on CCO_HOOK_MAIN (see resources/entry/cco-hook-bundle.mjs)
/**
 * Real end-to-end test against the Cursor CLI. Costs real usage.
 *
 * Creates an isolated temporary workspace, loads this plugin with --plugin-dir, and checks that:
 *  1. sessionStart initializes runtime + workspace agents and injects context,
 *  2. an expensive parent model delegates ordinary work to cco-fast (and the subagent runs on the mapped model),
 *  3. a cheap parent model escalates high-risk work to cco-deep,
 *  4. [cco:deep] / [cco:fast] overrides are honored,
 *  5. trivial questions are answered directly (no delegation overhead),
 *  6. decisions are logged.
 *
 *   node scripts/cco-e2e-real.mjs [--workspace <root-for-report>] [--keep-tmp] [--only <caseId,...>]
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { parseArgs, writeJson, readJsonl, workspacePaths, nowIso, TIERS, isMain } from "./lib/common.mjs";
import { runAgent } from "./lib/cli-run.mjs";
import { discover } from "./cco-discover-models.mjs";
import { snapshotCliModel, restoreCliModel } from "./lib/models.mjs";
import { PLUGIN_ROOT as REPO_PLUGIN_ROOT } from "./lib/common.mjs";
import { installHooks } from "./cco-install-hooks.mjs";
import { loadConfig } from "./lib/config.mjs";
import { BUNDLED_PRICING_PATH } from "./lib/pricing.mjs";

function makeWorkspace(root, name) {
  const ws = fs.mkdtempSync(path.join(root, `cco-e2e-${name}-`));
  fs.mkdirSync(path.join(ws, "config"), { recursive: true });
  fs.writeFileSync(path.join(ws, "config", "auth.js"), 'module.exports = { oauthSecret: process.env.OAUTH_SECRET, webhookKey: "abc" };\n');
  fs.writeFileSync(path.join(ws, "README.md"), "# e2e fixture\n");
  return ws;
}

function agentModel(ws, name) {
  try {
    const text = fs.readFileSync(path.join(ws, ".cursor", "agents", `${name}.md`), "utf8");
    return text.match(/^model:\s*(.+)$/m)?.[1]?.trim() || null;
  } catch {
    return null;
  }
}

export function buildCases(profiles) {
  return [
    {
      id: "expensive_parent_delegates_fast",
      parentModel: profiles.deep,
      prompt: 'Create utils/slugify.js exporting slugify(str) (lowercase, spaces to hyphens, strip non-alphanumerics) and utils/slugify.test.mjs using node:test asserting slugify("Hello World!") === "hello-world". Run node --test and report the result.',
      expect: { delegatedTo: ["cco-fast", "cco-balanced"], subagentModel: [profiles.fast, profiles.balanced], filesExist: ["utils/slugify.js", "utils/slugify.test.mjs"] }
    },
    {
      id: "cheap_parent_escalates_risky_to_deep",
      parentModel: profiles.fast,
      prompt: "We need to rotate the production OAuth secret and the payment webhook signing key used in config/auth.js. Implement dual-key support during rotation (old+new) with a rollback path and explain the deployment order. Keep it small.",
      expect: { delegatedTo: ["cco-deep"], subagentModel: [profiles.deep] }
    },
    {
      id: "override_deep_forces_deep",
      parentModel: profiles.fast,
      prompt: "[cco:deep] Add a one-line comment at the top of README.md saying this is a fixture.",
      expect: { delegatedTo: ["cco-deep"], subagentModel: [profiles.deep] }
    },
    {
      id: "override_fast_wins_over_risk",
      parentModel: profiles.deep,
      prompt: "[cco:fast] In config/auth.js rename the exported key webhookKey to webhookSigningKey (production auth config; keep behavior).",
      expect: { delegatedTo: ["cco-fast"], subagentModel: [profiles.fast] }
    },
    {
      id: "deep_task_on_frontier_chat_uses_explore_for_research",
      parentModel: profiles.deep,
      seedRepo: true,
      prompt: "Investigate how override tokens like [cco:deep] are parsed across scripts/lib and covered by the tests, then make the parser also accept the tokens when they appear inside inline code spans like `[cco:deep]`, keeping every existing test green. Run node --test test/ at the end.",
      expect: { researchTo: ["cco-explore"], noWorkDelegation: true }
    },
    {
      id: "trivial_question_no_delegation",
      parentModel: profiles.fast,
      mode: "ask",
      prompt: "quick: which git command shows the last 3 commits, one per line?",
      expect: { delegatedTo: [], resultMatches: /git log/i }
    }
  ];
}

function evaluate(testCase, run, ws) {
  const failures = [];
  const ccoTasks = run.tasks.filter((t) => String(t.subagent || "").startsWith("cco-"));
  const expect = testCase.expect;
  if (expect.delegatedTo) {
    if (expect.delegatedTo.length === 0 && ccoTasks.length > 0) {
      failures.push(`expected no delegation, got ${ccoTasks.map((t) => t.subagent).join(",")}`);
    }
    if (expect.delegatedTo.length > 0) {
      if (!ccoTasks.length) {
        failures.push("expected a cco-* delegation, none happened");
      } else if (!expect.delegatedTo.includes(ccoTasks[0].subagent)) {
        failures.push(`expected first delegation to ${expect.delegatedTo.join("|")}, got ${ccoTasks[0].subagent}`);
      }
    }
  }
  if (expect.subagentModel && ccoTasks.length) {
    const model = ccoTasks[0].model;
    if (!expect.subagentModel.includes(model)) {
      failures.push(`expected subagent model ${expect.subagentModel.join("|")}, got ${model}`);
    }
  }
  if (expect.filesExist) {
    for (const rel of expect.filesExist) {
      if (!fs.existsSync(path.join(ws, rel))) {
        failures.push(`missing file ${rel}`);
      }
    }
  }
  if (expect.researchTo) {
    const research = run.tasks.filter((t) => expect.researchTo.includes(t.subagent));
    if (!research.length) {
      failures.push(`expected a research delegation to ${expect.researchTo.join("|")}, none happened`);
    }
  }
  if (expect.noWorkDelegation && ccoTasks.some((t) => ["cco-fast", "cco-balanced", "cco-deep"].includes(t.subagent))) {
    failures.push("expected the deep work to stay in the chat (same model), but it was delegated");
  }
  if (expect.resultMatches && !expect.resultMatches.test(run.resultText)) {
    failures.push("result text did not match expectation");
  }
  if (run.isError) {
    failures.push(`agent run error (status ${run.status}) ${run.stderr.slice(0, 200)}`);
  }
  return failures;
}

function mainInner() {
  const args = parseArgs(process.argv.slice(2), { workspace: process.cwd(), "keep-tmp": false, only: null, timeout: 600 });
  const reportRoot = path.resolve(String(args.workspace));
  const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), "cco-e2e-"));
  const only = args.only ? String(args.only).split(",").map((s) => s.trim()) : null;

  // Discover once (with probes) in a seed workspace to learn the real mapping for this account.
  const seed = makeWorkspace(tmpRoot, "seed");
  fs.mkdirSync(path.dirname(workspacePaths(seed).pricingPath), { recursive: true });
  fs.copyFileSync(BUNDLED_PRICING_PATH, workspacePaths(seed).pricingPath);
  installHooks({ workspace: seed, pluginRoot: process.env.CCO_PLUGIN_ROOT });
  const runtime = discover({ workspace: seed, probe: true, writeAgents: true, config: loadConfig(seed) });
  const profiles = Object.fromEntries(TIERS.map((tier) => [tier, runtime.profiles[tier].model]));
  console.log(JSON.stringify({ discovered: profiles, degraded: runtime.health.degraded, notes: runtime.health.notes }, null, 2));
  const usable = TIERS.every((tier) => profiles[tier] !== "inherit");
  if (!usable) {
    console.error("Discovery could not map every tier to a runnable model; e2e needs three real models.");
    process.exit(2);
  }

  const cases = buildCases(profiles).filter((c) => !only || only.includes(c.id));
  const results = [];
  for (const testCase of cases) {
    const ws = makeWorkspace(tmpRoot, testCase.id);
    if (testCase.seedRepo) {
      for (const dir of ["scripts", "test", "config"]) {
        fs.cpSync(path.join(REPO_PLUGIN_ROOT, dir), path.join(ws, dir), { recursive: true });
      }
      fs.writeFileSync(path.join(ws, "package.json"), JSON.stringify({ name: "fixture", type: "module", private: true, scripts: { test: "node --test" } }, null, 2));
    }
    // Reuse the seed's discovered runtime so the session-start hook does not need to probe again.
    // Each case gets the seed's full .cursor setup (agents, hooks, config, mapping) before the session starts.
    fs.cpSync(path.join(seed, ".cursor"), path.join(ws, ".cursor"), { recursive: true });
    fs.rmSync(workspacePaths(ws).stateDir, { recursive: true, force: true });
    const started = Date.now();
    const run = runAgent({ workspace: ws, model: testCase.parentModel, prompt: testCase.prompt, mode: testCase.mode || "agent", plugin: true, timeoutMs: Number(args.timeout) * 1000 });
    const failures = evaluate(testCase, run, ws);
    const decisions = readJsonl(workspacePaths(ws).decisionsPath);
    const hooks = readJsonl(workspacePaths(ws).hooksLogPath);
    const gate = hooks.filter((h) => h.event === "preToolUse:gate");
    results.push({
      id: testCase.id,
      parentModel: testCase.parentModel,
      pass: failures.length === 0,
      failures,
      delegations: run.tasks.filter((t) => String(t.subagent || "").startsWith("cco-")).map((t) => ({ subagent: t.subagent, model: t.model })),
      workspaceAgentModels: { fast: agentModel(ws, "cco-fast"), balanced: agentModel(ws, "cco-balanced"), deep: agentModel(ws, "cco-deep") },
      gate: { denials: gate.filter((g) => g.action === "deny").length, allows: gate.filter((g) => g.action === "allow").length },
      decisionsLogged: decisions.length,
      parentUsage: run.usage,
      durationApiMs: run.durationApiMs,
      wallMs: Date.now() - started,
      tools: run.tools,
      resultPreview: run.resultText.slice(0, 300),
      workspace: ws
    });
    console.log(`${failures.length ? "FAIL" : "PASS"} ${testCase.id} ${failures.join("; ")}`);
  }

  const report = {
    generatedAt: nowIso(),
    cliVersion: runtime.cli.version,
    profiles,
    total: results.length,
    passed: results.filter((r) => r.pass).length,
    failed: results.filter((r) => !r.pass).length,
    results
  };
  const reportDir = path.join(reportRoot, ".ai", "cco");
  writeJson(path.join(reportDir, "e2e-real-report.json"), report);
  let md = "# CCO real Cursor E2E report\n\n";
  md += `- Generated: ${report.generatedAt}\n- CLI: ${report.cliVersion}\n- Tier models: fast=${profiles.fast}, balanced=${profiles.balanced}, deep=${profiles.deep}\n- Passed: ${report.passed}/${report.total}\n\n`;
  for (const r of results) {
    md += `## ${r.id} — ${r.pass ? "PASS" : "FAIL"}\n`;
    md += `- Parent model: ${r.parentModel}\n- Delegations: ${r.delegations.length ? r.delegations.map((d) => `${d.subagent} (${d.model})`).join(", ") : "none"}\n- Gate: ${r.gate.denials} denial(s), ${r.gate.allows} allow(s)\n- Decisions logged: ${r.decisionsLogged}\n- Parent usage: ${r.parentUsage ? `${r.parentUsage.inputTokens} in / ${r.parentUsage.outputTokens} out / ${r.parentUsage.cacheReadTokens} cache read` : "n/a"}\n- API time: ${r.durationApiMs} ms\n`;
    if (r.failures.length) {
      md += `- Failures: ${r.failures.join("; ")}\n`;
    }
    md += "\n";
  }
  fs.writeFileSync(path.join(reportDir, "e2e-real-report.md"), md);
  if (!args["keep-tmp"]) {
    fs.rmSync(tmpRoot, { recursive: true, force: true });
  } else {
    console.log(`kept temp workspaces under ${tmpRoot}`);
  }
  console.log(JSON.stringify({ reportPath: path.join(reportDir, "e2e-real-report.md"), passed: report.passed, failed: report.failed }, null, 2));
  process.exitCode = report.failed ? 1 : 0;
}

function main() {
  // Isolate: temp account home and a temp copy of the plugin, so neither the repo nor the account is touched.
  const isoRoot = fs.mkdtempSync(path.join(os.tmpdir(), "cco-iso-"));
  const pluginCopy = path.join(isoRoot, "plugin");
  fs.cpSync(REPO_PLUGIN_ROOT, pluginCopy, { recursive: true, filter: (src) => !/node_modules|\.git($|\/)/.test(src) });
  process.env.CCO_PLUGIN_ROOT = pluginCopy;
  // Every --model call persists into ~/.cursor/cli-config.json; put the user's model back afterwards.
  const snapshot = snapshotCliModel();
  const restore = () => {
    const r = restoreCliModel(snapshot);
    if (!r.restored) {
      console.error(`warning: could not restore CLI model (${r.reason})`);
    }
  };
  process.on("SIGINT", () => {
    restore();
    process.exit(130);
  });
  try {
    mainInner();
  } finally {
    restore();
  }
}

if (process.env.CCO_HOOK_MAIN === "cco-e2e-real.mjs") {
  main();
}
